// AcceptTOS.jsx
import React, { useState } from "react";
import LidService from "../../../Services/LidService";

const AcceptTOS = ({ onAccept }) => {
  const [isChecked, setIsChecked] = useState(false); // Track checkbox state

  const handleAccept = () => {
    LidService.AcceptTOS();
    window.location.reload();
  };

  return (
    <div
      style={{
        position: "fixed",
        top: 0,
        left: 0,
        width: "100vw",
        height: "100vh",
        backgroundColor: "rgba(0,0,0,0.5)",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        zIndex: 1000,
      }}
    >
      <div
        style={{
          backgroundColor: "#fff",
          borderRadius: "10px",
          maxWidth: "500px",
          width: "90%",
          maxHeight: "80vh",
          overflowY: "auto",
          padding: "20px",
          boxShadow: "0 10px 25px rgba(0,0,0,0.3)",
          textAlign: "center",
        }}
      >
        <h2>Terms of Service</h2>
        <p>
          Om gebruik te maken van All-Active-IT moeten de gebruikersvoorwaarden
          geaccepteerd worden, omdat u dit nog niet heeft gedaan op de nieuwste
          versie. Door op "Accepteren" te klikken gaat u akkoord met de
          <button
            style={{
              marginLeft: "5px",
              textDecoration: "underline",
              color: "blue",
              background: "none",
              border: "none",
              cursor: "pointer",
            }}
            onClick={() => window.open("/TermsofService", "_blank")}
          >
            gebruikersvoorwaarden
          </button>
          .
        </p>

        {/* Checkbox */}
        <div style={{ margin: "20px 0", textAlign: "left" }}>
          <label style={{ cursor: "pointer", fontSize: "14px" }}>
            <input
              type="checkbox"
              checked={isChecked}
              onChange={() => setIsChecked(!isChecked)}
              style={{ marginRight: "10px" }}
            />
            Ik heb de gebruikersvoorwaarden gelezen en ga akkoord
          </label>
        </div>

        {/* Accept Button */}
        <button
          onClick={handleAccept}
          disabled={!isChecked} // Button disabled until checkbox is checked
          style={{
            backgroundColor: isChecked ? "#4CAF50" : "#ccc",
            color: "#fff",
            border: "none",
            padding: "10px 20px",
            borderRadius: "5px",
            cursor: isChecked ? "pointer" : "not-allowed",
            fontSize: "16px",
          }}
        >
          Accept
        </button>
      </div>
    </div>
  );
};

export default AcceptTOS;
